// Generates src/schema.ts (Zod) from schema/result.schema.json. Run: npm run gen:schema -w shared
import { readFileSync, writeFileSync } from "node:fs";
import { jsonSchemaToZod } from "json-schema-to-zod";

const schemaPath = new URL("../schema/result.schema.json", import.meta.url);
const outPath = new URL("../src/schema.ts", import.meta.url);

const schema = JSON.parse(readFileSync(schemaPath, "utf8"));
const code = jsonSchemaToZod(schema, { name: "resultSchema", module: "esm", type: "Result" });
const header =
  "// GENERATED by `npm run gen:schema -w shared` from shared/schema/result.schema.json. Do not edit.\n";
writeFileSync(outPath, header + code + "\n");
console.log(`wrote ${outPath.pathname}`);
